// Check if there is an on-site search box or search endpoint on amtrak.com
const searchElements = await browserjs(tabId, () => {
  const inputs = Array.from(document.querySelectorAll('input[type="search"], input[name*="search" i], input[placeholder*="search" i]'));
  const searchButtons = Array.from(document.querySelectorAll('button, a')).filter(el => /search/i.test(el.getAttribute('aria-label') || el.innerText || ''));
  return {
    inputs: inputs.map(i => ({ name: i.name, placeholder: i.placeholder, id: i.id })),
    searchButtons: searchButtons.map(b => ({ text: b.innerText.trim(), label: b.getAttribute('aria-label'), href: b.href }))
  };
});
console.log("Search elements:", JSON.stringify(searchElements, null, 2));

