const tabId = 730410078;

// Let's search if "real id" appears in the HTML of the passenger identification page or anywhere
const checkRealId = await browserjs(tabId, async () => {
  const res = await fetch("https://www.amtrak.com/planning-booking/tickets-id-safety-security/passenger-identification");
  const html = await res.text();
  return {
    hasRealId: /real\s*id/i.test(html)
  };
});
console.log("Real ID mentioned on passenger-identification page?", checkRealId);

